    custodyAuth: TAccountMetas[6];
    custody: TAccountMetas[7];
    vaultAuth: TAccountMetas[8];
    vault: TAccountMetas[9];
    treasuryAuth: TAccountMetas[10];
    treasury: TAccountMetas[11];
